/* MSG-01 · Lista de Hilos — panel de contenido.
   Ningún color literal: todo sale de los tokens de
   openspec/architecture/design-system.md §1 (ver :root global). */

.panel {
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
}

.bar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.searchForm {
  flex: 1;
  min-width: 180px;
  max-width: 300px;
}

.search {
  width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-surface-mist);
  color: var(--bw-input-text);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  outline: none;
  transition: border-color 0.15s;
}

.search:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.search::placeholder {
  color: var(--bw-input-placeholder);
}

.newContact {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.primary {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
}

/* El botón existe pero no lleva a DIR-01: se ve apagado, no verde de mentira. */
.primary:disabled {
  background: var(--bw-line-steel);
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.scope {
  max-width: 280px;
  font-size: 11px;
  color: var(--bw-steel-mist);
  line-height: 1.4;
}

.count {
  margin-left: auto;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.error {
  margin-bottom: 12px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: var(--bw-size-input);
  line-height: 1.5;
}

.loading {
  margin: 0 0 10px;
  font-size: var(--bw-size-input);
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.page {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  cursor: pointer;
  transition: border-color 0.12s, color 0.12s;
}

.page:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.page:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.pageCtrl {
  color: var(--bw-input-placeholder);
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

