import { useEffect, useState, type FormEvent } from 'react';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — la pantalla.
 *
 * No es un componente de presentación: es la dueña del estado (búsqueda y
 * página) y la única que toca red, a través de `fetchThreadPage`. Todo lo que se
 * puede calcular sin base —tono del estado, vista previa, tiempo relativo— vive
 * en `lib/threads.ts` y no se reescribe aquí.
 *
 * La búsqueda se aplica al pulsar Enter (spec §3), no en cada tecla: el filtrado
 * es server-side sobre toda la tabla, y filtrar por tecla multiplicaría las
 * consultas sin cambiar el resultado.
 */

/**
 * Traduce lo que rechaza PostgREST a algo que se pueda leer en pantalla.
 *
 * Lo que se captura NO es siempre un `Error`: PostgREST rechaza con un objeto
 * plano `{ code, message }`, así que `String(e)` da `[object Object]` y
 * `e.message` da `undefined`. Es F-020 literal, y un aviso que se come el código
 * deja al usuario (y a quien depura) sin el `PGRST201` que explica el fallo
 * entero. Por eso se sacan `code` y `message` cuando existen y se pintan junto a
 * la frase para humanos (F-128).
 */
function describeError(cause: unknown): string {
  const headline = 'No se pudieron cargar los hilos.';

  if (cause instanceof Error) {
    return cause.message !== '' ? `${headline} (${cause.message})` : headline;
  }

  if (typeof cause === 'object' && cause !== null) {
    const { code, message } = cause as { code?: unknown; message?: unknown };
    const bits: string[] = [];
    if (typeof code === 'string' && code !== '') bits.push(code);
    if (typeof message === 'string' && message !== '') bits.push(message);
    if (bits.length > 0) return `${headline} (${bits.join(' · ')})`;
    try {
      const json = JSON.stringify(cause);
      if (json !== '' && json !== undefined && json !== '{}') return `${headline} (${json})`;
    } catch {
      // Objeto circular: no hay nada legible que enseñar de él.
    }
    return headline;
  }

  return `${headline} (${String(cause)})`;
}

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * MSG-02 no existe cuando se escribió MSG-01 y abrir un hilo no lleva a ningún
   * sitio. La prop se declara porque es la firma pública del componente y el
   * shell la pasa desde `App.tsx` (F-118): sin ella el repo no compila en un
   * fichero que este nodo no escribe. **Se recibe y se ignora**: lo que hay en
   * `out_of_scope` sigue fuera, entero.
   */
  onOpenThread?: (threadId: string) => void;
}

export function Messages({ profile, now }: Props) {
  const currentTime = now ?? new Date();
  const orgId = profile.orgId;

  const [draft, setDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId, search, page })
      .then((res) => {
        if (!alive) return;
        setThreads(res.threads);
        setTotal(res.total);
      })
      .catch((cause: unknown) => {
        if (!alive) return;
        setThreads([]);
        setTotal(0);
        setError(describeError(cause));
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [orgId, search, page]);

  const totalPages = pageCount(total);

  function applySearch() {
    setSearch(draft.trim());
    setPage(1);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    applySearch();
  }

  // MSG-02 no está en el alcance: abrir un hilo no lleva a ninguna parte. La
  // fila sigue siendo pulsable (y sigue siendo `listitem`), pero no navega.
  const handleOpen = () => {
    // Sin destino todavía: ver F-118.
  };

  return (
    <div className={styles.panel}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.bar}>
        <form className={styles.searchForm} onSubmit={handleSubmit}>
          <input
            className={styles.search}
            type="text"
            value={draft}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                applySearch();
              }
            }}
          />
        </form>

        <div className={styles.newContact}>
          {/* Deshabilitado y con el motivo visible: DIR-01 no está entre las
              ocho pantallas del alcance (Plan §9). F-023 e, F-128. */}
          <button type="button" className={styles.primary} disabled>
            Nuevo contacto
          </button>
          <span data-testid="directorio-scope" className={styles.scope}>
            Este botón abre el Directorio de organizaciones (DIR-01), que queda fuera del MVP.
          </span>
        </div>

        <span data-testid="pag-info" className={styles.count}>
          {`${total.toLocaleString('es-ES')} hilos · Página ${page} de ${totalPages}`}
        </span>
      </div>

      {error !== null && (
        <div role="alert" className={styles.error}>
          {error}
        </div>
      )}

      {loading && <p className={styles.loading}>Cargando hilos…</p>}

      <ThreadList threads={threads} now={currentTime} onOpen={handleOpen} />

      <nav className={styles.pagination} aria-label="Paginación de hilos">
        <button
          type="button"
          className={`${styles.page} ${styles.pageCtrl}`}
          aria-label="Página anterior"
          disabled={page <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          <i className="ti ti-chevron-left" aria-hidden="true" />
        </button>

        {/* El número va como TEXTO del botón y estos botones NO llevan
            `aria-label`: el nombre accesible lo decide el `aria-label` en cuanto
            existe, así que `aria-label="Página 2"` haría que el botón se llamara
            eso y no `2`. F-145. */}
        {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
          <button
            key={p}
            type="button"
            className={`${styles.page} ${p === page ? styles.pageActive : ''}`}
            onClick={() => setPage(p)}
          >
            {p}
          </button>
        ))}

        <button
          type="button"
          className={`${styles.page} ${styles.pageCtrl}`}
          aria-label="Página siguiente"
          disabled={page >= totalPages}
          onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
        >
          <i className="ti ti-chevron-right" aria-hidden="true" />
        </button>
      </nav>
    </div>
  );
}

