/* MSG-01 · Lista de Hilos — filas y estado vacío.
   Ningún color literal: todo sale de los tokens de
   openspec/architecture/design-system.md §1 (ver :root global). */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

/* El botón es el que hace la fila pulsable; el `listitem` sigue siendo el <li>. */
.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  background: none;
  font-family: var(--bw-font-body);
  text-align: left;
  cursor: pointer;
  transition: background 0.1s;
}

.rowButton:hover {
  background: var(--bw-row-hover-tint);
}

.rowButton:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.top {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.country {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: var(--bw-radius);
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.time {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
  justify-self: end;
}

.preview {
  font-size: 12px;
  color: var(--bw-steel-mist);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  justify-self: end;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

/* Los cinco tonos van DESPUÉS de .badge: misma especificidad, gana el último. */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border-color: var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
  border-color: var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border-color: var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* Estado vacío: contenedor propio, nunca un <li> dentro del <ul>. */
.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 40px 24px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  text-align: center;
}

.emptyText {
  margin: 0;
  max-width: 520px;
  font-size: 14px;
  color: var(--bw-ink-steel);
  line-height: 1.6;
}

.emptyAction {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
}

.emptyAction:disabled {
  background: var(--bw-line-steel);
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.emptyWhy {
  margin: 0;
  max-width: 460px;
  font-size: 12px;
  color: var(--bw-steel-mist);
  line-height: 1.5;
}

