import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01.
 *
 * Presentacional y sin estado: pinta las filas **en el orden que las recibe**
 * (el orden es del servidor, `last_item_at` descendente) y avisa con el ID del
 * hilo cuando alguien abre una. No carga datos ni pagina.
 *
 * Tres cosas de este fichero no son maquetación y no se pueden "mejorar":
 *
 * 1. La fila es un `<li>` con un `<button>` DENTRO, nunca un `role` encima. Un
 *    `role="button"` en el `<li>` lo saca de `listitem` —el rol explícito
 *    sustituye al implícito, no se suma— y el contrato consulta `listitem`
 *    nueve veces. Poner los dos crea un segundo botón con el mismo nombre
 *    accesible y las consultas por rol dejan de ser unívocas. F-131.
 * 2. El estado vacío va en un `<div>` FUERA de cualquier `<ul>`: con `threads`
 *    vacío el contrato exige que no quede ningún `listitem` en el documento.
 *    F-141.
 * 3. El diccionario de tonos se declara `Record<StateTone, string | undefined>`,
 *    nunca `Record<StateTone, string>`: con `noUncheckedIndexedAccess` activo
 *    cualquier propiedad de un módulo CSS puede no existir y TypeScript la tipa
 *    `string | undefined`. El `??` va en el único punto de consumo, para que una
 *    clase que falte deje la fila sin adorno en vez de escribir la palabra
 *    `undefined` en el atributo `class`. F-143.
 *
 * El botón `Ir al Directorio` del estado vacío existe pero está `disabled`, y el
 * motivo (`fuera del MVP`) es visible: DIR-01 no está entre las ocho pantallas
 * del alcance, así que un botón que parece pulsable y no lleva a ningún sitio es
 * exactamente lo que CLAUDE.md §7 prohíbe. Misma forma que el botón de subida de
 * INV-01 (F-023 e, F-128).
 */

/** Tono del badge → clase CSS. Ver F-143 en el comentario de arriba. */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** El ID del hilo, no el objeto: quien navega solo necesita el identificador. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: Props) {
  if (threads.length === 0) {
    // Estado vacío. La frase del spec va ENTERA y en UN SOLO nodo de texto: el
    // contrato la busca con `getByText` a cadena exacta, y eso compara el texto
    // de un elemento, no el de un contenedor con hijos (F-147). Partirla en
    // título y cuerpo dejaría el aserto sin nada que encontrar.
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras
          organizaciones.
        </p>
        <button type="button" className={styles.emptyAction} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyWhy}>
          El Directorio de organizaciones (DIR-01) queda fuera del MVP, así que este botón
          todavía no lleva a ningún sitio.
        </p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          <button
            type="button"
            className={styles.rowButton}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.top}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry !== '' && (
                <span className={styles.country}>{thread.counterpartyCountry}</span>
              )}
            </span>
            <span className={styles.time}>{relativeTime(thread.lastItemAt, now)}</span>
            {/* Metadatos y nada más: tipo de elemento y referencia en claro. La
                vista previa nunca muestra contenido descifrado (spec §7). */}
            <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
            <span className={`${styles.badge} ${TONE_CLASS[stateTone(thread.state)] ?? ''}`}>
              {thread.state}
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
